<script setup lang="ts">import{computed,onMounted,ref}from"vue";import{useRoute}from"vue-router";import BaseEmptyState from"@/components/base/BaseEmptyState.vue";import BasePageHeader from"@/components/base/BasePageHeader.vue";import{availabilityRepository}from"@/domain/repositories";import type{AvailabilityRecord}from"@/types/records";const route=useRoute(),items=ref<AvailabilityRecord[]>([]),loading=ref(true),error=ref("");const created=computed(()=>route.query.created==="1"),updated=computed(()=>route.query.updated==="1");async function load(){loading.value=true;error.value="";try{const page=await availabilityRepository.list({perPage:100,filter:"ativo = true",sort:"provider_nome",expand:"titulo,pais"});items.value=page.items}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}const title=(i:AvailabilityRecord)=>i.expand?.titulo?.titulo||i.titulo;const country=(i:AvailabilityRecord)=>i.expand?.pais?.nome||i.expand?.pais?.codigo||"Global";const price=(i:AvailabilityRecord)=>i.preco===null||i.preco===undefined?"":new Intl.NumberFormat("pt-PT",{style:"currency",currency:i.moeda||"EUR"}).format(i.preco);onMounted(()=>void load());</script><template><div v-if="created" class="form-alert form-alert-success">Disponibilidade criada com sucesso.</div><div v-if="updated" class="form-alert form-alert-success">Disponibilidade atualizada com sucesso.</div><BasePageHeader eyebrow="Disponibilidade" title="VOD" description="Streaming, aluguer, compra, gratuito e outras formas de acesso."><template #actions><RouterLink class="button button-primary" to="/vod/novo">＋ Adicionar disponibilidade</RouterLink></template></BasePageHeader><section v-if="loading" class="page-loading"><span class="loader"/></section><BaseEmptyState v-else-if="error" icon="!" title="Não foi possível carregar o VOD" :description="error"><button class="button button-secondary" @click="load">Voltar a tentar</button></BaseEmptyState><div v-else-if="items.length" class="vod-grid"><article v-for="item in items" :key="item.id" class="panel vod-card"><div class="vod-card-head"><div><span class="detail-badge detail-badge-primary">{{item.tipo}}</span><h2>{{title(item)}}</h2></div><RouterLink class="button button-secondary" :to="`/vod/${item.id}/editar`">Editar</RouterLink></div><dl class="vod-facts"><div><dt>Provider</dt><dd>{{item.provider_nome}}</dd></div><div><dt>País</dt><dd>{{country(item)}}</dd></div><div><dt>Qualidade</dt><dd>{{item.qualidade||"—"}}</dd></div><div><dt>Preço</dt><dd>{{price(item)|| (item.incluido_subscricao?'Incluído':'—')}}</dd></div></dl><a v-if="item.url" class="button button-primary" :href="item.url" target="_blank" rel="noopener noreferrer">Abrir provider</a></article></div><BaseEmptyState v-else icon="▶" title="Ainda não existem disponibilidades VOD" description="Adiciona a primeira oferta de streaming, aluguer, compra ou acesso gratuito."/></template>
